import React, { useState, useEffect } from 'react';
import axios from 'axios';
import '../../visualPage/CadastroProfessores.css'; // Importe o arquivo CSS

const CadastroProfessores = () => {
  const [professores, setProfessores] = useState([]);
  const [nome, setNome] = useState('');
  const [email, setEmail] = useState('');
  const [dataCadastro, setDataCadastro] = useState('');
  const [isActive, setIsActive] = useState(true); // Estado para controle de ativo/inativo
  const [editingProfessor, setEditingProfessor] = useState(null); // Para editar o professor atual

  // Função para buscar a lista de professores do servidor
  useEffect(() => {
    fetchProfessores();
  }, []);

  const fetchProfessores = async () => {
    try {
      const response = await axios.get('http://localhost:5000/api/professores');
      setProfessores(response.data);
    } catch (err) {
      console.error('Erro ao consultar professores:', err);
    }
  };

  // Função para criar um novo professor
  const handleCreateProfessor = async () => {
    try {
      await axios.post('http://localhost:5000/api/professores', {
        nome,
        email,
        dataCadastro,
        isActive,
      });
      fetchProfessores(); // Atualiza a lista após a criação
      clearFields(); // Limpa os campos após criar
    } catch (err) {
      console.error('Erro ao criar professor:', err);
    }
  };

  // Função para editar um professor
  const handleEditProfessor = async (id) => {
    try {
      await axios.put(`http://localhost:5000/api/professores/${id}`, {
        nome,
        email,
        dataCadastro,
        isActive,
      });
      fetchProfessores(); // Atualiza a lista após a edição
      clearFields();
      setEditingProfessor(null); // Limpa o estado de edição
    } catch (err) {
      console.error('Erro ao editar professor:', err);
    }
  };

  // Função para excluir um professor
  const handleDeleteProfessor = async (id) => {
    try {
      await axios.delete(`http://localhost:5000/api/professores/${id}`);
      fetchProfessores(); // Atualiza a lista após a exclusão
    } catch (err) {
      console.error('Erro ao excluir professor:', err);
    }
  };

  // Função para iniciar a edição de um professor
  const handleEditClick = (professor) => {
    setNome(professor.nome);
    setEmail(professor.email);
    setDataCadastro(professor.dataCadastro);
    setIsActive(professor.isActive);
    setEditingProfessor(professor.id); // Define o professor atual para edição
  };

  // Função para limpar os campos do formulário
  const clearFields = () => {
    setNome('');
    setEmail('');
    setDataCadastro('');
    setIsActive(true); // Por padrão, ativo
    setEditingProfessor(null); // Sai do modo de edição
  };

  return (
    <div className="container-cadastro-professores">
      <h2>Cadastro de Professores</h2>
      <div className="form-container">
        <input
          type="text"
          placeholder="Nome"
          value={nome}
          onChange={(e) => setNome(e.target.value)}
        />
        <input
          type="email"
          placeholder="Email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
        />
        <input
          type="date"
          placeholder="Data de Cadastro"
          value={dataCadastro}
          onChange={(e) => setDataCadastro(e.target.value)}
        />

        {/* Checkbox para inativar professor */}
        <div>
          <label>
            <input
              type="checkbox"
              checked={!isActive} // Quando marcado, o professor será inativo
              onChange={(e) => setIsActive(!e.target.checked)} // Alterar estado ativo/inativo
            />
            Inativar professor
          </label>
        </div>
      </div>

      {/* Botões para ação */}
      <div className="buttons">
        {editingProfessor ? (
          <button onClick={() => handleEditProfessor(editingProfessor)}>Salvar</button>
        ) : (
          <button onClick={handleCreateProfessor}>Novo</button>
        )}
        <button onClick={clearFields}>Cancelar</button>
      </div>

      <div className="lista-professores">
        <h3>Professores Cadastrados</h3>
        <ul>
          {professores.map((professor) => (
            <li key={professor.id}>
              {professor.nome} - {professor.email}
              <button onClick={() => handleEditClick(professor)}>Editar</button>
              <button onClick={() => handleDeleteProfessor(professor.id)}>Excluir</button>
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
};

export default CadastroProfessores;
